# Verify all old songs have been removed from existing playlists and are in the Archived Songs playlist
old_song_ids = {74, 280, 261, 311, 29, 43, 162, 128, 207, 308, 257, 172, 131, 127}
playlist_ids = [443, 444, 445, 446, 447, 448]

all_removed = True
for pid in playlist_ids:
    playlist = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    songs = playlist.get("songs", [])
    remaining_old = [s["id"] for s in songs if s["id"] in old_song_ids]
    if remaining_old:
        all_removed = False
        print(f"Playlist {pid} still has old songs: {remaining_old}")
    else:
        print(f"Playlist {pid} clean")

# Verify Archived Songs playlist (654) contains all 14 old songs
archived = apis.spotify.show_playlist(playlist_id=654, access_token=spotify_token)
archived_song_ids = {s["id"] for s in archived.get("songs", [])}
missing = old_song_ids - archived_song_ids
if missing:
    print(f"Missing from Archived Songs: {missing}")
else:
    print("All 14 old songs are in Archived Songs playlist")

print(f"All removals successful: {all_removed}")

